example_item.example_item_data:
% L'axe frontal et les intervalles globaux d'un enregistrement simule a douze derivations.
recording = ecglab.simulate('Seconds', 20, 'Rate', 500, 'Leads', 12, 'Seed', 1);
result = ecglab.leads(recording);
result.axis.degrees

% Les derivations des membres derivees de I et II, et les PR, QRS et QT avec leurs plages.
recording = ecglab.simulate('Seconds', 20, 'Rate', 500, 'Leads', {'I', 'II'}, 'Seed', 1);
result = ecglab.leads(recording);
result.derived.leads
result.normal
